#ifndef WALLET_BACKUP_H
#define WALLET_BACKUP_H

/*
 * Encrypted wallet backup file (milestone M6), format version 1. Pure functions: no I/O, no
 * randomness (the caller passes salt and nonce from the health-tested RNG).
 *
 *   key  = Argon2id(password = 16-byte entropy of the 12-word backup password, salt,
 *                   m = m_kib KiB, t = passes, p = 1)            -> 32 bytes
 *   file = header || ChaCha20-Poly1305(key, nonce, aad = header, payload) || tag || check
 *
 * The backup password is 12 BIP39 words generated by the device (128 bits + 4-bit checksum),
 * so typos are caught before the slow key derivation, and guessing is hopeless whatever the
 * Argon2 settings; Argon2id is defence in depth. The settings are stored in the file, so
 * stronger ones (more memory on the PCB) stay readable by any firmware that has the memory.
 *
 * Layout (little-endian, 140 bytes):
 *     0  magic "TREDDERB"
 *     8  format version (1)
 *     9  flags: bit 0 = DEMO (written by a demo build without a security chip)
 *    10  KDF algorithm (2 = Argon2id v1.3)
 *    11  KDF lanes (1)
 *    12  KDF memory, KiB (u32)
 *    16  KDF passes (u32)
 *    20  salt (16)
 *    36  nonce (12)
 *    48  payload length (u16, = 64)
 *    50  reserved (u16, 0)
 *    52  encrypted payload (64)
 *   116  Poly1305 tag (16)
 *   132  check: first 8 bytes of SHA-256(bytes 0..131). NOT a security feature: lets the device
 *        tell "damaged file" from "wrong password" before spending seconds on Argon2.
 *
 * Payload (64 bytes, plaintext): version (1), word count, flags (bit 0 = blind signing on),
 * reserved (0), 24 word indices (u16, unused = 0), 12 zero bytes. Every field is validated
 * after decryption, including the seed's BIP39 checksum.
 *
 * The BIP39 passphrase (if any) is never in the backup: it is something the user remembers.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "wallet/status.h"

#define WL_BACKUP_FILE_LEN 140u
#define WL_BACKUP_PW_WORDS 12u
#define WL_BACKUP_SALT_LEN 16u
#define WL_BACKUP_NONCE_LEN 12u
#define WL_BACKUP_MAX_PASSES 64u
#define WL_BACKUP_MIN_KIB 8u

typedef struct {
  uint32_t m_kib;   /* Argon2 memory; the caller provides m_kib * 1024 bytes of work area */
  uint32_t passes;
} wl_kdf_t;

typedef struct {
  uint8_t words;      /* 12, 15, 18, 21 or 24 */
  uint16_t idx[24];
  bool blind_signing;
} wl_backup_payload_t;

typedef struct {
  bool demo;
  wl_kdf_t kdf;
  uint8_t salt[WL_BACKUP_SALT_LEN];
} wl_backup_info_t;

/* Encrypt. pw: the 12 backup-password word indices (must have a valid BIP39 checksum). */
wl_status_t wl_backup_seal(const wl_backup_payload_t *p, const uint16_t pw[WL_BACKUP_PW_WORDS], bool demo,
                           wl_kdf_t kdf, const uint8_t salt[WL_BACKUP_SALT_LEN],
                           const uint8_t nonce[WL_BACKUP_NONCE_LEN], void *work, size_t work_size,
                           uint8_t out[WL_BACKUP_FILE_LEN]);

/* Structure + checksum only, no password: WL_ERR_FORMAT (not a v1 backup or unsupported
   settings), WL_ERR_DAMAGED (checksum), or WL_OK with the header fields. */
wl_status_t wl_backup_inspect(const uint8_t *file, size_t len, wl_backup_info_t *info);

/* Decrypt and validate. WL_ERR_CHECKSUM: the password words have a bad checksum (typo, nothing
   tried); WL_ERR_ARG: the KDF needs more work area than given; WL_ERR_AUTH: wrong password or
   altered file. On any error *p is zeroed. */
wl_status_t wl_backup_open(const uint8_t *file, size_t len, const uint16_t pw[WL_BACKUP_PW_WORDS], void *work,
                           size_t work_size, wl_backup_payload_t *p);

#endif
